void nrproto_splitString( char *src  )
{
	int i,c=0;
	char *decoded;

#ifdef nrproto__ENCRYPT
	decoded = nrproto.cryptwork;
	nrproto_decodeString( src , decoded );
#else
	decoded = src;
#endif
	if( nrproto.log_callback ) {
		nrproto.log_callback( decoded );
	}
	if( nrproto_readlogfilename[0] != '\0'){
		FILE *rfp;
		rfp = fopen( nrproto_readlogfilename , "a+" );
		if(rfp) fprintf( rfp, "%s\n",decoded );
		if(rfp) fclose(rfp);
	}
	for(i = 0 ; ; i++ ){
		if( decoded[i] == '\0' ) break;
		if( i==0){
		    nrproto.token_list[c++]=&(decoded[i]);
		}
		if( decoded[i]== ' '  || decoded[i]== 0x17 ){
		    nrproto.token_list[c++]=&(decoded[i+1]);
		}
	}
	while( *decoded ){
		if( ( *decoded  ) == ' ' || (*decoded ) == '\n' || (*decoded ) == '\r' ) *decoded = '\0';
		decoded++;
 	}
	nrproto.token_list[c] = (char*) NULL;
}

int nrproto_demkstr_int(const char*a )
{
	if( a == (char*) NULL) return 0;
/*	return (int) strtol( a ,NULL , 10);*/
	return nrproto_a62toi( a );
}

int nrproto_a62toi(const char *a )
{
	int ret = 0;
	int minus ;
	if( a[0] == '-' ){
		minus = -1;
        a++;
	} else {
		minus = 1;
	}

	while( *a != '\0' )
	{
		ret *= 62;
		if( '0' <= (*a) && (*a) <= '9' )
			ret += (*a)-'0';
		else
		if( 'a' <= (*a) && (*a) <= 'z' )
			ret += (*a)-'a'+10;
		else
		if( 'A' <= (*a) && (*a) <= 'Z' )
			ret += (*a)-'A'+36;
		else
			return 0;
		a++;
	}
	return ret * minus;
}

